struction</label><textarea class="form-control mb-3" name="instructions" rows="5"><?= esc($method['instructions']) ?></textarea><div class="row g-2 mt-auto"><div class="col"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active" <?= $method['status']==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= $method['status']==='inactive'?'selected':'' ?>>Inactive</option></select></div><div class="col"><label class="form-label">Sort order</label><input class="form-control" type="number" name="sort_order" value="<?= (int)$method['sort_order'] ?>"></div></div><button class="btn btn-success mt-3">Save changes</button></form></div><?php endforeach ?></div>
